package com.bankstonks;

import com.bankstonks.model.LotValuation;
import com.bankstonks.model.TrackedItem;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

@Singleton
public class BankOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final PortfolioManager manager;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;
	private final BankStonksConfig config;

	@Inject
	public BankOverlay(Client client, PortfolioManager manager, ItemManager itemManager,
		TooltipManager tooltipManager, BankStonksConfig config)
	{
		this.client = client;
		this.manager = manager;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.bankOverlay() || !manager.hasAccount())
		{
			return;
		}

		int boughtId = manager.boughtIdForBankItem(itemId);
		if (boughtId < 0)
		{
			return;
		}

		TrackedItem tracked = manager.getTracked(boughtId);
		if (tracked == null || tracked.totalBought() <= 0)
		{
			return;
		}

		if (PortfolioManager.isBlocked(config, itemManager.getItemComposition(boughtId).getName()))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		int quantity = Math.min(tracked.totalBought(), widgetItem.getQuantity());
		if (quantity <= 0)
		{
			return;
		}

		LotValuation valuation = tracked.value(quantity);
		long avg = valuation.getAveragePrice();
		long rawCurrent = itemManager.getItemPrice(boughtId);
		long current = config.applyGeTax() ? PortfolioManager.netAfterTax(rawCurrent) : rawCurrent;
		long profit = (current - avg) * quantity;

		java.awt.Color plColor = profit >= 0 ? config.profitColor() : config.lossColor();

		String heldAge = Format.age(valuation.getHeldSinceEpochMs());
		String heldLine = heldAge.isEmpty() ? "" : "Held: " + heldAge + "</br>";

		String text = quantity + " @ " + Format.plain(avg) + " ea</br>"
			+ heldLine
			+ "P/L: " + ColorUtil.wrapWithColorTag(Format.gp(profit), plColor);

		tooltipManager.add(new Tooltip(text));
	}
}

package com.bankstonks;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BankStonksConfig.GROUP)
public interface BankStonksConfig extends Config
{
	String GROUP = "bankstonks";
	String KEY_BLOCK_LIST = "blockList";
	String KEY_SORT_ORDER = "sortOrder";

	@ConfigSection(
		name = "Display",
		description = "How the sidebar list is shown.",
		position = 0
	)
	String SECTION_DISPLAY = "display";

	@ConfigSection(
		name = "Bank overlay",
		description = "Profit/loss drawn on your bank slots.",
		position = 1
	)
	String SECTION_OVERLAY = "overlay";

	@ConfigSection(
		name = "Colours",
		description = "Colours for gains and losses.",
		position = 2
	)
	String SECTION_COLOURS = "colours";

	@ConfigSection(
		name = "Block list",
		description = "Items to hide from the list.",
		position = 3
	)
	String SECTION_BLOCK_LIST = "blockListSection";

	@ConfigItem(
		keyName = "showPercent",
		name = "Show profit %",
		description = "Show the profit/loss as a percentage of the amount invested.",
		section = SECTION_DISPLAY,
		position = 1
	)
	default boolean showPercent()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SORT_ORDER,
		name = "Sort by",
		description = "How to order the items in the panel.",
		section = SECTION_DISPLAY,
		position = 2
	)
	default SortOrder sortOrder()
	{
		return SortOrder.BIGGEST_MOVERS;
	}

	@ConfigItem(
		keyName = "applyGeTax",
		name = "Subtract GE tax",
		description = "Value holdings at what you would net after the 2% GE sell tax (capped at 5M per item) instead of the raw wiki price.",
		section = SECTION_DISPLAY,
		position = 3
	)
	default boolean applyGeTax()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bankOverlay",
		name = "Show bank overlay",
		description = "Draw each tracked item's profit/loss directly on its slot in the bank.",
		section = SECTION_OVERLAY,
		position = 1
	)
	default boolean bankOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "profitColor",
		name = "Profit colour",
		description = "Colour used for a gain.",
		section = SECTION_COLOURS,
		position = 1
	)
	default Color profitColor()
	{
		return new Color(76, 175, 80);
	}

	@Alpha
	@ConfigItem(
		keyName = "lossColor",
		name = "Loss colour",
		description = "Colour used for a loss.",
		section = SECTION_COLOURS,
		position = 2
	)
	default Color lossColor()
	{
		return new Color(244, 67, 54);
	}

	@ConfigItem(
		keyName = KEY_BLOCK_LIST,
		name = "Block list",
		description = "Comma-separated item names that are never shown in the list (they are still tracked in the background). A name with no * must match exactly; a name with a * matches any item containing that text, e.g. '*potion*' blocks all potions and 'prayer potion*' blocks all doses.",
		section = SECTION_BLOCK_LIST,
		position = 1
	)
	default String blockList()
	{
		return "";
	}
}

package com.bankstonks;

import com.bankstonks.model.PortfolioRow;
import com.bankstonks.ui.BankStonksPanel;
import com.bankstonks.ui.PortfolioActions;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.event.HierarchyEvent;
import java.awt.image.BufferedImage;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@PluginDescriptor(
	name = "Bank Stonks",
	description = "Tracks GE buys and shows live profit/loss vs the wiki price for what you hold",
	tags = {"grand", "exchange", "ge", "profit", "loss", "portfolio", "stonks", "flip", "price", "bank"}
)
public class BankStonksPlugin extends Plugin implements PortfolioActions
{
	private static final int BANK_GROUP_ID = 12;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private BankStonksConfig config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private PortfolioManager manager;
	@Inject
	private GrandExchangeBuyTracker buyTracker;
	@Inject
	private BankTracker bankTracker;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private BankOverlay bankOverlay;

	private BankStonksPanel panel;
	private NavigationButton navButton;

	/**
	 * Rebuilds wait for the next game tick and an open sidebar, so the flood of container changes
	 * during play costs one rebuild, or none while the panel is closed.
	 */
	private volatile boolean refreshPending;

	private volatile boolean forceRebuild;

	private Map<Integer, Integer> heldSignatureAtLastRebuild = new HashMap<>();

	@Provides
	BankStonksConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankStonksConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		panel = new BankStonksPanel(itemManager::getImage, config, this);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/nav_button.png");
		navButton = NavigationButton.builder()
			.tooltip("Bank Stonks")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(bankOverlay);

		panel.addHierarchyListener(this::refreshWhenShown);

		requestForceRefresh();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(bankOverlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	private void refreshWhenShown(HierarchyEvent event)
	{
		boolean showingChanged = (event.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0;
		if (showingChanged && panel.isShowing())
		{
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		boolean offersAboutToReplay = state == GameState.LOGGING_IN || state == GameState.HOPPING;
		if (offersAboutToReplay)
		{
			buyTracker.setLoginSync(true);
		}
		if (state == GameState.LOGGED_IN)
		{
			// Now rather than at the next rebuild: the bank overlay needs the account loaded.
			manager.setAccount(client.getAccountHash());
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The login/hop offer replay all arrives before the first tick.
		buyTracker.setLoginSync(false);

		if (refreshPending && panel != null && panel.isShowing())
		{
			refreshPending = false;
			rebuildIfForcedOrHoldingsChanged();
		}
	}

	private void rebuildIfForcedOrHoldingsChanged()
	{
		Map<Integer, Integer> signature = manager.trackedHeldSignature(liveHeldQuantities());
		if (forceRebuild || !signature.equals(heldSignatureAtLastRebuild))
		{
			forceRebuild = false;
			heldSignatureAtLastRebuild = signature;
			refresh();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == BANK_GROUP_ID)
		{
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (buyTracker.handle(event))
		{
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		boolean bankChanged = bankTracker.handle(event);
		int id = event.getContainerId();
		if (bankChanged || id == InventoryID.INV || id == InventoryID.WORN)
		{
			requestRefreshIfHoldingsChanged();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (isSettingChange(event))
		{
			requestForceRefresh();
		}
	}

	private static boolean isSettingChange(ConfigChanged event)
	{
		return BankStonksConfig.GROUP.equals(event.getGroup()) && !isPortfolioSave(event);
	}

	private static boolean isPortfolioSave(ConfigChanged event)
	{
		return event.getKey().startsWith(PortfolioManager.DATA_KEY_PREFIX);
	}

	@Schedule(period = 5, unit = ChronoUnit.MINUTES)
	public void refreshPrices()
	{
		requestForceRefresh();
	}

	private void requestRefreshIfHoldingsChanged()
	{
		refreshPending = true;
	}

	private void requestForceRefresh()
	{
		forceRebuild = true;
		refreshPending = true;
	}

	private void refresh()
	{
		if (panel == null)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				manager.setAccount(client.getAccountHash());
			}

			if (!manager.hasAccount())
			{
				panel.showLoggedOut();
				return;
			}

			List<PortfolioRow> rows = manager.buildRows(itemManager, config, liveHeldQuantities());
			panel.update(rows, manager.getLastTotalProfit());
		});
	}

	/** Client thread only. */
	private Map<Integer, Integer> liveHeldQuantities()
	{
		Map<Integer, Integer> out = new HashMap<>();
		addContainer(out, InventoryID.INV);
		addContainer(out, InventoryID.WORN);
		addQuiver(out);
		return out;
	}

	/** The quiver keeps its ammo in varplayers, not in an item container. */
	private void addQuiver(Map<Integer, Integer> out)
	{
		int ammoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		int ammoQty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (ammoId > 0 && ammoQty > 0)
		{
			out.merge(itemManager.canonicalize(ammoId), ammoQty, Integer::sum);
		}
	}

	private void addContainer(Map<Integer, Integer> out, int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			int unnotedId = itemManager.canonicalize(item.getId());
			out.merge(unnotedId, item.getQuantity(), Integer::sum);
		}
	}

	@Override
	public void addManual(String query, int quantity, long priceEach, long heldSinceEpochMs)
	{
		clientThread.invokeLater(() ->
		{
			if (!manager.hasAccount())
			{
				panel.setStatus("Log in first.", Color.GRAY);
				return;
			}

			int itemId = resolveItemId(query);
			if (itemId <= 0)
			{
				panel.setStatus("No item found for \"" + query + "\".", config.lossColor());
				return;
			}

			String name = itemManager.getItemComposition(itemId).getName();
			unblock(name);
			manager.recordBuy(itemId, quantity, priceEach * quantity, heldSinceEpochMs);
			manager.save();
			panel.setStatus("Added " + quantity + " x " + name + ".", Color.LIGHT_GRAY);
			panel.clearManualEntry();
			refresh();
		});
	}

	private void unblock(String itemName)
	{
		configManager.setConfiguration(BankStonksConfig.GROUP, BankStonksConfig.KEY_BLOCK_LIST, BlockLists.remove(config.blockList(), itemName));
	}

	@Override
	public void untrackItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.removeItem(itemId);
			manager.save();
			refresh();
		});
	}

	@Override
	public void untrackLot(int itemId, int quantity, long spent, long epochMs)
	{
		clientThread.invokeLater(() ->
		{
			manager.removeLot(itemId, quantity, spent, epochMs);
			manager.save();
			refresh();
		});
	}

	@Override
	public void blockItem(String itemName)
	{
		configManager.setConfiguration(BankStonksConfig.GROUP, BankStonksConfig.KEY_BLOCK_LIST, BlockLists.add(config.blockList(), itemName));
		refresh();
	}

	@Override
	public void lockItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.lockItem(itemId);
			manager.save();
			refresh();
		});
	}

	@Override
	public void lockLot(int itemId, int quantity, long spent, long epochMs)
	{
		clientThread.invokeLater(() ->
		{
			manager.lockLot(itemId, quantity, spent, epochMs);
			manager.save();
			refresh();
		});
	}

	@Override
	public void unlockItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.unlockItem(itemId);
			manager.save();
			refresh();
		});
	}

	@Override
	public void setSortOrder(SortOrder order)
	{
		configManager.setConfiguration(BankStonksConfig.GROUP, BankStonksConfig.KEY_SORT_ORDER, order);
	}

	private int resolveItemId(String query)
	{
		List<ItemPrice> results = itemManager.search(query);
		if (results == null || results.isEmpty())
		{
			return -1;
		}
		for (ItemPrice result : results)
		{
			if (result.getName().equalsIgnoreCase(query))
			{
				return result.getId();
			}
		}
		return results.get(0).getId();
	}
}

package com.bankstonks;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;

/**
 * The game only sends the bank's contents while it is open, so the last snapshot is kept for when
 * it is closed.
 */
@Slf4j
@Singleton
public class BankTracker
{
	private final PortfolioManager manager;

	@Inject
	public BankTracker(PortfolioManager manager)
	{
		this.manager = manager;
	}

	/** @return whether the bank snapshot was updated */
	public boolean handle(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK || !manager.hasAccount())
		{
			return false;
		}

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return false;
		}

		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
		}

		manager.updateBank(quantities);
		manager.save();
		return true;
	}
}

package com.bankstonks;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

final class BlockLists
{
	// Compiled once per CSV value: matches() runs for bank items on every frame.
	private static volatile String cachedCsv;
	private static volatile List<Pattern> cachedPatterns = Collections.emptyList();

	private BlockLists()
	{
	}

	static List<String> names(String csv)
	{
		List<String> out = new ArrayList<>();
		if (csv == null)
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String trimmed = part.trim();
			if (!trimmed.isEmpty())
			{
				out.add(trimmed);
			}
		}
		return out;
	}

	static boolean matches(String csv, String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		List<Pattern> patterns = compiled(csv);
		if (patterns.isEmpty())
		{
			return false;
		}
		String lower = itemName.toLowerCase(Locale.ROOT);
		for (Pattern pattern : patterns)
		{
			if (pattern.matcher(lower).find())
			{
				return true;
			}
		}
		return false;
	}

	private static List<Pattern> compiled(String csv)
	{
		String key = csv == null ? "" : csv;
		if (key.equals(cachedCsv))
		{
			return cachedPatterns;
		}
		List<Pattern> patterns = new ArrayList<>();
		for (String entry : names(csv))
		{
			patterns.add(toPattern(entry.toLowerCase(Locale.ROOT)));
		}
		cachedPatterns = patterns;
		cachedCsv = key;
		return patterns;
	}

	/** A wildcard entry matches anywhere in the name, so "* potion" also catches "Prayer potion(4)". */
	private static Pattern toPattern(String entry)
	{
		boolean exactNameOnly = entry.indexOf('*') < 0;
		StringBuilder regex = new StringBuilder();
		if (exactNameOnly)
		{
			regex.append('^');
		}
		String[] parts = entry.split("\\*", -1);
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				regex.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				regex.append(Pattern.quote(parts[i]));
			}
		}
		if (exactNameOnly)
		{
			regex.append('$');
		}
		return Pattern.compile(regex.toString());
	}

	static String add(String csv, String name)
	{
		List<String> names = names(csv);
		for (String existing : names)
		{
			if (existing.equalsIgnoreCase(name))
			{
				return csv == null ? "" : csv;
			}
		}
		names.add(name);
		return String.join(", ", names);
	}

	static String remove(String csv, String name)
	{
		List<String> names = names(csv);
		names.removeIf(n -> n.equalsIgnoreCase(name));
		return String.join(", ", names);
	}
}

package com.bankstonks;

public final class Format
{
	private Format()
	{
	}

	/** Signed and compact, e.g. "+1.23M", "-450.0K". */
	public static String gp(long value)
	{
		long abs = Math.abs(value);
		String sign = value > 0 ? "+" : (value < 0 ? "-" : "");
		if (abs >= 1_000_000_000L)
		{
			return sign + String.format("%.2fB", abs / 1_000_000_000.0);
		}
		if (abs >= 1_000_000L)
		{
			return sign + String.format("%.2fM", abs / 1_000_000.0);
		}
		if (abs >= 1_000L)
		{
			return sign + String.format("%.1fK", abs / 1_000.0);
		}
		return sign + abs;
	}

	public static String exact(long value)
	{
		return String.format("%,d", value);
	}

	/** Unsigned and compact, e.g. "1.23M", "450.0K". */
	public static String plain(long value)
	{
		if (value >= 1_000_000_000L)
		{
			return String.format("%.2fB", value / 1_000_000_000.0);
		}
		if (value >= 1_000_000L)
		{
			return String.format("%.2fM", value / 1_000_000.0);
		}
		if (value >= 1_000L)
		{
			return String.format("%.1fK", value / 1_000.0);
		}
		return Long.toString(value);
	}

	/** Empty when the time is unknown (0 or less). */
	public static String age(long sinceEpochMs)
	{
		if (sinceEpochMs <= 0)
		{
			return "";
		}
		long days = (System.currentTimeMillis() - sinceEpochMs) / 86_400_000L;
		if (days <= 0)
		{
			return "today";
		}
		if (days < 30)
		{
			return days + "d";
		}
		long months = days / 30;
		if (months < 12)
		{
			return months + "mo";
		}
		long years = months / 12;
		long remMonths = months % 12;
		return remMonths > 0 ? years + "y " + remMonths + "mo" : years + "y";
	}
}

package com.bankstonks;

import com.bankstonks.model.Lot;
import com.bankstonks.model.SlotState;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;

/**
 * Offer events carry the offer's running totals, so each fill is the difference from the slot's
 * last-seen state. {@code getSpent()} is what was actually paid across fills at different prices,
 * so spend is accumulated rather than derived from a price.
 */
@Slf4j
@Singleton
public class GrandExchangeBuyTracker
{
	private final PortfolioManager manager;

	/**
	 * True while the client replays the existing offers on login/hop. An offer with no baseline then
	 * was recorded in an earlier session, so it becomes the baseline instead of being recorded again.
	 */
	private volatile boolean loginSync;

	@Inject
	public GrandExchangeBuyTracker(PortfolioManager manager)
	{
		this.manager = manager;
	}

	public void setLoginSync(boolean syncing)
	{
		this.loginSync = syncing;
	}

	/** @return whether a buy fill was recorded */
	public boolean handle(GrandExchangeOfferChanged event)
	{
		if (!manager.hasAccount())
		{
			return false;
		}

		final int slot = event.getSlot();
		final GrandExchangeOffer offer = event.getOffer();
		final GrandExchangeOfferState state = offer.getState();

		if (!isBuy(state))
		{
			forgetSlot(slot);
			return false;
		}

		final int itemId = offer.getItemId();
		final int quantitySold = offer.getQuantitySold();
		final long spent = offer.getSpent();

		SlotState prev = manager.getSlot(slot);
		boolean continuing = prev != null && prev.getItemId() == itemId && quantitySold >= prev.getQuantitySold();
		int prevQty = continuing ? prev.getQuantitySold() : 0;
		long prevSpent = continuing ? prev.getSpent() : 0;

		int deltaQty = quantitySold - prevQty;
		long deltaSpent = spent - prevSpent;

		long offerId = continuing ? prev.getLotId() : Lot.NO_OFFER;

		boolean recorded = false;
		if (deltaQty > 0 && deltaSpent > 0)
		{
			boolean adoptAsBaseline = loginSync && !continuing;
			if (adoptAsBaseline)
			{
				log.debug("login sync: adopting baseline item={} qty={} spent={} (not recorded)", itemId, quantitySold, spent);
			}
			else
			{
				if (offerId == Lot.NO_OFFER)
				{
					offerId = manager.nextOfferId();
				}
				manager.recordOfferFill(itemId, deltaQty, deltaSpent, System.currentTimeMillis(), offerId);
				recorded = true;
				log.debug("recorded buy fill: item={} qty={} spent={} offer={}", itemId, deltaQty, deltaSpent, offerId);
			}
		}

		manager.setSlot(slot, new SlotState(itemId, quantitySold, spent, offerId));
		manager.save();
		return recorded;
	}

	/**
	 * Not during the login/hop replay: the client empties every slot before replaying the real
	 * offers, and clearing then would lose the baseline and split the offer's fills into a new lot.
	 */
	private void forgetSlot(int slot)
	{
		if (loginSync)
		{
			return;
		}
		manager.clearSlot(slot);
		manager.save();
	}

	private static boolean isBuy(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}
}

package com.bankstonks;

import com.bankstonks.model.Lot;
import com.bankstonks.model.LotValuation;
import com.bankstonks.model.PortfolioData;
import com.bankstonks.model.PortfolioRow;
import com.bankstonks.model.SlotState;
import com.bankstonks.model.TrackedItem;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemMapping;
import net.runelite.client.game.ItemVariationMapping;

/** Not thread-safe: use it from the client thread only. */
@Slf4j
@Singleton
public class PortfolioManager
{
	static final String CONFIG_GROUP = "bankstonks";
	static final String DATA_KEY_PREFIX = "data_";

	private final ConfigManager configManager;
	private final Gson gson;

	private long accountHash = -1L;
	private PortfolioData data = new PortfolioData();

	@Inject
	public PortfolioManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Loads the account's saved portfolio, unless it is already the current account. */
	public void setAccount(long hash)
	{
		if (hash == accountHash)
		{
			return;
		}
		accountHash = hash;
		load();
	}

	public boolean hasAccount()
	{
		return accountHash != -1L;
	}

	private void load()
	{
		if (accountHash == -1L)
		{
			data = new PortfolioData();
			return;
		}
		String json = configManager.getConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + accountHash);
		if (json == null || json.isEmpty())
		{
			data = new PortfolioData();
		}
		else
		{
			try
			{
				data = gson.fromJson(json, PortfolioData.class);
				if (data == null)
				{
					data = new PortfolioData();
				}
				data.ensureInitialized();
			}
			catch (Exception e)
			{
				log.warn("failed to parse stored portfolio for account {}, starting fresh", accountHash, e);
				data = new PortfolioData();
			}
		}
	}

	public void save()
	{
		if (accountHash == -1L)
		{
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + accountHash, gson.toJson(data));
	}

	public SlotState getSlot(int slot)
	{
		return data.getSlots().get(slot);
	}

	public void setSlot(int slot, SlotState state)
	{
		data.getSlots().put(slot, state);
	}

	public void clearSlot(int slot)
	{
		data.getSlots().remove(slot);
	}

	/** @param heldSinceEpochMs 0 or less means now */
	public void recordBuy(int itemId, int quantity, long spent, long heldSinceEpochMs)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		long epochMs = heldSinceEpochMs > 0 ? heldSinceEpochMs : System.currentTimeMillis();
		data.getItems().computeIfAbsent(itemId, id -> new TrackedItem()).addBuy(quantity, spent, epochMs);
	}

	public void recordOfferFill(int itemId, int quantity, long spent, long epochMs, long offerId)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		data.getItems().computeIfAbsent(itemId, id -> new TrackedItem()).addOfferFill(offerId, quantity, spent, epochMs);
	}

	public long nextOfferId()
	{
		long id = data.getNextLotId() + 1;
		data.setNextLotId(id);
		return id;
	}

	public TrackedItem getTracked(int itemId)
	{
		return data.getItems().get(itemId);
	}

	/** Deletes the item's buy history, so it only comes back with a new buy. */
	public void removeItem(int itemId)
	{
		data.getItems().remove(itemId);
	}

	/** Removing the last lot untracks the item. */
	public void removeLot(int itemId, int quantity, long spent, long epochMs)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked == null)
		{
			return;
		}
		List<Lot> lots = tracked.getLots();
		for (int i = 0; i < lots.size(); i++)
		{
			if (lots.get(i).matches(quantity, spent, epochMs))
			{
				lots.remove(i);
				break;
			}
		}
		if (lots.isEmpty())
		{
			data.getItems().remove(itemId);
		}
	}

	public void lockItem(int itemId)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.lockToNewest();
		}
	}

	public void lockLot(int itemId, int quantity, long spent, long epochMs)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.lockToLot(quantity, spent, epochMs);
		}
	}

	public void unlockItem(int itemId)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.unlock();
		}
	}

	private static void addHeld(Map<Integer, Integer> heldByBase, int itemId, int quantity)
	{
		for (int base : tradeableBasesOf(itemId))
		{
			heldByBase.merge(base, quantity, Integer::sum);
		}
	}

	private static final int AVERNIC_DEFENDER = 22322;
	private static final int AVERNIC_DEFENDER_HILT = 22477;

	/**
	 * Untradeable assembled items that {@link ItemMapping} does not cover, mapped to the tradeable
	 * parts they are made from.
	 */
	private static final Map<Integer, int[]> ASSEMBLED_COMPONENTS = new HashMap<>();

	static
	{
		ASSEMBLED_COMPONENTS.put(AVERNIC_DEFENDER, new int[]{AVERNIC_DEFENDER_HILT});
	}

	private static Set<Integer> tradeableBasesOf(int itemId)
	{
		Set<Integer> bases = new HashSet<>();
		int[] components = ASSEMBLED_COMPONENTS.get(itemId);
		if (components != null)
		{
			for (int component : components)
			{
				bases.add(ItemVariationMapping.map(component));
			}
			return bases;
		}
		Collection<ItemMapping> mappings = ItemMapping.map(itemId);
		if (mappings != null)
		{
			for (ItemMapping mapping : mappings)
			{
				if (isAssembledPart(mapping))
				{
					bases.add(ItemVariationMapping.map(mapping.getTradeableItem()));
				}
			}
		}
		if (bases.isEmpty())
		{
			bases.add(ItemVariationMapping.map(itemId));
		}
		return bases;
	}

	/** Excludes bulk charges (scales, darts): they get used up, so they must not count as held. */
	private static boolean isAssembledPart(ItemMapping mapping)
	{
		return mapping.getQuantity() == 1;
	}

	/** Matches across variants and assembled items; -1 when nothing tracked matches. */
	public int boughtIdForBankItem(int bankItemId)
	{
		if (data.getItems().containsKey(bankItemId))
		{
			return bankItemId;
		}
		Set<Integer> bases = tradeableBasesOf(bankItemId);
		for (Integer id : data.getItems().keySet())
		{
			if (bases.contains(ItemVariationMapping.map(id)))
			{
				return id;
			}
		}
		return -1;
	}

	public static boolean isBlocked(BankStonksConfig config, String itemName)
	{
		return BlockLists.matches(config.blockList(), itemName);
	}

	public void updateBank(Map<Integer, Integer> bankQuantities)
	{
		data.setBank(bankQuantities);
	}

	private volatile long lastTotalProfit;

	public long getLastTotalProfit()
	{
		return lastTotalProfit;
	}

	private static final double GE_TAX_RATE = 0.02;
	private static final long GE_TAX_CAP_PER_ITEM = 5_000_000L;
	private static final long GE_TAX_FREE_BELOW = 50;

	/** Buys are never taxed, so only the selling side of a profit goes through this. */
	public static long netAfterTax(long price)
	{
		if (price < GE_TAX_FREE_BELOW)
		{
			return price;
		}
		long tax = Math.min((long) Math.floor(price * GE_TAX_RATE), GE_TAX_CAP_PER_ITEM);
		return price - tax;
	}

	/**
	 * Values at most the amount bought, so items got outside the GE (drops etc.) never count as
	 * profit, and sold stock drops out. Held is the bank snapshot plus {@code liveQuantities}: an
	 * item is only ever in one of them, so nothing counts twice.
	 */
	public List<PortfolioRow> buildRows(ItemManager itemManager, BankStonksConfig config, Map<Integer, Integer> liveQuantities)
	{
		Map<Integer, Integer> heldByBase = heldQuantitiesByBase(liveQuantities);
		List<PortfolioRow> rows = lockedRows(itemManager, config);
		rows.addAll(heldRows(itemManager, config, heldByBase));
		sort(rows, config.sortOrder());
		lastTotalProfit = totalProfit(rows);
		return rows;
	}

	/** Cheap (no pricing), so it can be compared every tick to tell whether tracked holdings changed. */
	public Map<Integer, Integer> trackedHeldSignature(Map<Integer, Integer> liveQuantities)
	{
		if (data.getItems().isEmpty())
		{
			return new HashMap<>();
		}
		Map<Integer, Integer> held = heldQuantitiesByBase(liveQuantities);
		Map<Integer, Integer> signature = new HashMap<>();
		for (Integer base : trackedBasesWithSetPieces())
		{
			int quantity = held.getOrDefault(base, 0);
			if (quantity != 0)
			{
				signature.put(base, quantity);
			}
		}
		return signature;
	}

	private Map<Integer, Integer> heldQuantitiesByBase(Map<Integer, Integer> liveQuantities)
	{
		Map<Integer, Integer> heldByBase = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : data.getBank().entrySet())
		{
			addHeld(heldByBase, e.getKey(), e.getValue());
		}
		if (liveQuantities != null)
		{
			for (Map.Entry<Integer, Integer> e : liveQuantities.entrySet())
			{
				addHeld(heldByBase, e.getKey(), e.getValue());
			}
		}
		return heldByBase;
	}

	private Set<Integer> trackedBasesWithSetPieces()
	{
		Set<Integer> bases = new HashSet<>();
		for (Integer id : data.getItems().keySet())
		{
			bases.add(ItemVariationMapping.map(id));
			int[] pieces = ItemSets.piecesFor(id);
			if (pieces != null)
			{
				for (int piece : pieces)
				{
					bases.add(ItemVariationMapping.map(piece));
				}
			}
		}
		return bases;
	}

	private List<PortfolioRow> lockedRows(ItemManager itemManager, BankStonksConfig config)
	{
		List<PortfolioRow> rows = new ArrayList<>();
		for (Map.Entry<Integer, TrackedItem> entry : data.getItems().entrySet())
		{
			TrackedItem tracked = entry.getValue();
			if (!tracked.isLocked())
			{
				continue;
			}
			int itemId = entry.getKey();
			if (!isBlocked(config, itemManager.getItemComposition(itemId).getName()))
			{
				rows.add(buildLockedRow(itemManager, config, itemId, tracked));
			}
		}
		return rows;
	}

	private List<PortfolioRow> heldRows(ItemManager itemManager, BankStonksConfig config, Map<Integer, Integer> heldByBase)
	{
		List<PortfolioRow> rows = new ArrayList<>();
		for (Map.Entry<Integer, TrackedItem> entry : unlockedNewestBuyFirst())
		{
			int itemId = entry.getKey();
			TrackedItem tracked = entry.getValue();
			if (isBlocked(config, itemManager.getItemComposition(itemId).getName()))
			{
				continue;
			}
			int quantity = claimHeld(heldByBase, itemId, tracked.totalBought());
			if (quantity > 0)
			{
				rows.add(buildRow(itemManager, config, itemId, tracked, quantity));
			}
		}
		return rows;
	}

	/**
	 * Newest buy first, so when held items could belong to either a set or its loose pieces, the
	 * more recent purchase claims them, as with the LIFO cost basis.
	 */
	private List<Map.Entry<Integer, TrackedItem>> unlockedNewestBuyFirst()
	{
		List<Map.Entry<Integer, TrackedItem>> claims = new ArrayList<>();
		for (Map.Entry<Integer, TrackedItem> entry : data.getItems().entrySet())
		{
			if (!entry.getValue().isLocked() && entry.getValue().totalBought() > 0)
			{
				claims.add(entry);
			}
		}
		claims.sort((a, b) ->
		{
			int cmp = Long.compare(newestBuyEpochMs(b.getValue()), newestBuyEpochMs(a.getValue()));
			return cmp != 0 ? cmp : Integer.compare(a.getKey(), b.getKey());
		});
		return claims;
	}

	private static int claimHeld(Map<Integer, Integer> heldByBase, int itemId, int totalBought)
	{
		int[] pieces = ItemSets.piecesFor(itemId);
		if (pieces != null)
		{
			return claimSet(heldByBase, itemId, pieces, totalBought);
		}
		int base = ItemVariationMapping.map(itemId);
		int quantity = Math.min(totalBought, heldByBase.getOrDefault(base, 0));
		consume(heldByBase, base, quantity);
		return quantity;
	}

	private static int claimSet(Map<Integer, Integer> heldByBase, int setItemId, int[] pieces, int totalBought)
	{
		int setBase = ItemVariationMapping.map(setItemId);
		int unopened = heldByBase.getOrDefault(setBase, 0);
		int quantity = Math.min(totalBought, unopened + completeSets(heldByBase, pieces));
		if (quantity <= 0)
		{
			return quantity;
		}
		int fromUnopened = Math.min(quantity, unopened);
		consume(heldByBase, setBase, fromUnopened);
		int fromPieces = quantity - fromUnopened;
		for (int piece : pieces)
		{
			consume(heldByBase, ItemVariationMapping.map(piece), fromPieces);
		}
		return quantity;
	}

	private static int completeSets(Map<Integer, Integer> heldByBase, int[] pieces)
	{
		int completeSets = Integer.MAX_VALUE;
		for (int piece : pieces)
		{
			completeSets = Math.min(completeSets, heldByBase.getOrDefault(ItemVariationMapping.map(piece), 0));
		}
		return completeSets == Integer.MAX_VALUE ? 0 : completeSets;
	}

	private static long totalProfit(List<PortfolioRow> rows)
	{
		long total = 0;
		for (PortfolioRow row : rows)
		{
			total += row.getProfitTotal();
		}
		return total;
	}

	private static long newestBuyEpochMs(TrackedItem tracked)
	{
		long newest = 0;
		for (Lot lot : tracked.getLots())
		{
			if (lot.getEpochMs() > newest)
			{
				newest = lot.getEpochMs();
			}
		}
		return newest;
	}

	private static void consume(Map<Integer, Integer> heldByBase, int base, int amount)
	{
		if (amount <= 0)
		{
			return;
		}
		int remaining = heldByBase.getOrDefault(base, 0) - amount;
		if (remaining > 0)
		{
			heldByBase.put(base, remaining);
		}
		else
		{
			heldByBase.remove(base);
		}
	}

	private PortfolioRow buildRow(ItemManager itemManager, BankStonksConfig config, int itemId, TrackedItem tracked, int quantity)
	{
		LotValuation valuation = tracked.value(quantity);
		long avg = valuation.getAveragePrice();
		long rawCurrent = itemManager.getItemPrice(itemId);
		long effectiveCurrent = config.applyGeTax() ? netAfterTax(rawCurrent) : rawCurrent;
		long profitEach = effectiveCurrent - avg;
		long profitTotal = profitEach * quantity;

		List<Lot> lots = new ArrayList<>(tracked.getLots());
		lots.sort(Comparator.comparingLong(Lot::getEpochMs).reversed());

		String name = itemManager.getItemComposition(itemId).getName();
		return new PortfolioRow(itemId, name, quantity, avg, rawCurrent, profitEach, profitTotal, valuation.getHeldSinceEpochMs(), lots, false);
	}

	private PortfolioRow buildLockedRow(ItemManager itemManager, BankStonksConfig config, int itemId, TrackedItem tracked)
	{
		Lot locked = tracked.getLockedLot();
		int quantity = locked.getQuantity();
		long avg = locked.unitPrice();
		long rawCurrent = itemManager.getItemPrice(itemId);
		long effectiveCurrent = config.applyGeTax() ? netAfterTax(rawCurrent) : rawCurrent;
		long profitEach = effectiveCurrent - avg;
		long profitTotal = profitEach * quantity;

		List<Lot> hiddenHistory = new ArrayList<>();
		String name = itemManager.getItemComposition(itemId).getName();
		return new PortfolioRow(itemId, name, quantity, avg, rawCurrent, profitEach, profitTotal, locked.getEpochMs(), hiddenHistory, true);
	}

	private static void sort(List<PortfolioRow> rows, SortOrder order)
	{
		final Comparator<PortfolioRow> comparator;
		switch (order)
		{
			case MOST_PROFIT:
				comparator = Comparator.comparingLong(PortfolioRow::getProfitTotal).reversed();
				break;
			case MOST_LOSS:
				comparator = Comparator.comparingLong(PortfolioRow::getProfitTotal);
				break;
			case HIGHEST_VALUE:
				comparator = Comparator.comparingLong((PortfolioRow r) -> r.getCurrentPrice() * r.getQuantity()).reversed();
				break;
			case NAME:
				comparator = Comparator.comparing(r -> r.getName().toLowerCase());
				break;
			case BIGGEST_MOVERS:
			default:
				comparator = Comparator.comparingLong((PortfolioRow r) -> Math.abs(r.getProfitTotal())).reversed();
				break;
		}
		rows.sort(comparator);
	}
}

package com.bankstonks;

public enum SortOrder
{
	BIGGEST_MOVERS("Biggest movers"),
	MOST_PROFIT("Most profit"),
	MOST_LOSS("Most loss"),
	HIGHEST_VALUE("Highest value"),
	NAME("Name (A-Z)");

	private final String label;

	SortOrder(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.bankstonks.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class Lot
{
	public static final long NO_OFFER = 0;

	private int quantity;
	private long spent;
	private long epochMs;
	private long offerId;

	public long unitPrice()
	{
		return quantity <= 0 ? 0 : spent / quantity;
	}

	public boolean matches(int quantity, long spent, long epochMs)
	{
		return this.quantity == quantity && this.spent == spent && this.epochMs == epochMs;
	}
}

package com.bankstonks.model;

import lombok.Value;

@Value
public class LotValuation
{
	long averagePrice;

	/** The newest buy among the valued units, not the oldest. */
	long heldSinceEpochMs;
}

package com.bankstonks.model;

import java.util.HashMap;
import java.util.Map;
import lombok.Data;

/**
 * Saved as JSON with Gson: the field names here and in the classes it holds are the stored keys,
 * so renaming one loses that data for every existing user.
 */
@Data
public class PortfolioData
{
	private Map<Integer, TrackedItem> items = new HashMap<>();

	/** Item id to quantity, as of the last time the bank was open. */
	private Map<Integer, Integer> bank = new HashMap<>();

	private Map<Integer, SlotState> slots = new HashMap<>();

	/** The last offer id handed out, not the next one. */
	private long nextLotId;

	public void ensureInitialized()
	{
		if (items == null)
		{
			items = new HashMap<>();
		}
		for (TrackedItem item : items.values())
		{
			if (item != null)
			{
				item.ensureInitialized();
			}
		}
		if (bank == null)
		{
			bank = new HashMap<>();
		}
		if (slots == null)
		{
			slots = new HashMap<>();
		}
	}
}

