package com.bankstonks.ui;

import com.bankstonks.SortOrder;

/** The plugin does the work on the client thread and refreshes the panel afterwards. */
public interface PortfolioActions
{
	/**
	 * Records a buy for the item whose name best matches {@code query}.
	 *
	 * @param heldSinceEpochMs when it was bought, or 0 for now
	 */
	void addManual(String query, int quantity, long priceEach, long heldSinceEpochMs);

	/** Deletes the item's whole history; it reappears, fresh, only if bought again. */
	void untrackItem(int itemId);

	void untrackLot(int itemId, int quantity, long spent, long epochMs);

	/** Hides the item for good but keeps tracking it. Undone only by editing the block list in settings. */
	void blockItem(String itemName);

	/** Locks the item to its most recent buy: it stays listed and is valued at that buy. */
	void lockItem(int itemId);

	void lockLot(int itemId, int quantity, long spent, long epochMs);

	void unlockItem(int itemId);

	/** Changes the same setting as the config panel. */
	void setSortOrder(SortOrder order);
}

package com.bankstonks.ui;

import com.bankstonks.Format;
import com.bankstonks.model.PortfolioRow;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.ToolTipManager;

final class SummaryCard extends Widgets.Card
{
	private static final int OVERLINE_HEIGHT = 12;
	private static final int TOTAL_HEIGHT = 24;
	private static final int HEIGHT = 2 * Theme.CARD_PAD + OVERLINE_HEIGHT + Theme.SPACE_XS + TOTAL_HEIGHT;

	private long total;
	private long invested;
	private int items;
	private Color color = Theme.TEXT_MUTED;
	private boolean showPercent = true;

	private final Rectangle totalArea = new Rectangle();
	private final Rectangle pctArea = new Rectangle();

	SummaryCard()
	{
		super(null);
		ToolTipManager.sharedInstance().registerComponent(this);
	}

	void set(List<PortfolioRow> rows, long total, Color color, boolean showPercent)
	{
		this.total = total;
		this.invested = totalPaid(rows);
		this.items = rows.size();
		this.color = color;
		this.showPercent = showPercent;
		repaint();
	}

	private static long totalPaid(List<PortfolioRow> rows)
	{
		long sum = 0;
		for (PortfolioRow row : rows)
		{
			sum += row.getAverageBuyPrice() * row.getQuantity();
		}
		return sum;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(0, HEIGHT);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, HEIGHT);
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		if (totalArea.contains(e.getPoint()))
		{
			return (total > 0 ? "+" : "") + Format.exact(total) + " gp";
		}
		if (pctArea.contains(e.getPoint()))
		{
			return "Of " + Format.exact(invested) + " gp paid; worth " + Format.exact(invested + total) + " gp now";
		}
		return null;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2 = Theme.smooth(g);
		int left = Theme.CARD_PAD;
		int right = getWidth() - Theme.CARD_PAD;
		int overlineTop = Theme.CARD_PAD;
		int totalTop = overlineTop + OVERLINE_HEIGHT + Theme.SPACE_XS;
		paintOverline(g2, left, right, overlineTop);
		paintTotalAndPercent(g2, left, right, totalTop);
		g2.dispose();
	}

	private void paintOverline(Graphics2D g2, int left, int right, int top)
	{
		g2.setFont(Theme.small());
		FontMetrics small = g2.getFontMetrics();
		g2.setColor(Theme.TEXT_FAINT);
		g2.drawString("SINCE YOU BOUGHT", left, Widgets.baseline(small, top, OVERLINE_HEIGHT));
		String count = items == 1 ? "1 item" : items + " items";
		g2.drawString(count, right - small.stringWidth(count), Widgets.baseline(small, top, OVERLINE_HEIGHT));
	}

	private void paintTotalAndPercent(Graphics2D g2, int left, int right, int top)
	{
		Graphics2D hero = (Graphics2D) g2.create();
		hero.setFont(Theme.hero());
		Theme.smoothText(hero);
		FontMetrics heroMetrics = hero.getFontMetrics();
		String totalText = Format.gp(total);
		hero.setColor(color);
		int totalBaseline = Widgets.baseline(heroMetrics, top, TOTAL_HEIGHT);
		hero.drawString(totalText, left, totalBaseline);
		hero.dispose();
		totalArea.setBounds(left, top, heroMetrics.stringWidth(totalText), TOTAL_HEIGHT);
		pctArea.setBounds(0, 0, 0, 0);
		if (showPercent && invested > 0)
		{
			g2.setFont(Theme.small());
			String pct = total == 0 ? "0.0%" : String.format("%+.1f%%", total * 100.0 / invested);
			int chipLeft = Widgets.paintChip(g2, pct, right, (int) Math.round(Widgets.capCenter(heroMetrics, totalBaseline)), color);
			pctArea.setBounds(chipLeft, top, right - chipLeft, TOTAL_HEIGHT);
		}
	}
}

package com.bankstonks.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

final class Theme
{
	static final Color CANVAS = ColorScheme.DARKER_GRAY_COLOR;
	static final Color SURFACE = new Color(46, 46, 46);
	static final Color SURFACE_HOVER = new Color(55, 55, 55);
	static final Color INSET_SURFACE = new Color(38, 38, 38);
	static final Color OUTLINE = new Color(60, 60, 60);

	static final Color TEXT = Color.WHITE;
	static final Color TEXT_MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color TEXT_FAINT = new Color(120, 120, 120);

	static final Color ACCENT = ColorScheme.BRAND_ORANGE;
	static final Color ACCENT_HOVER = new Color(240, 158, 30);
	static final Color TEXT_ON_ACCENT = new Color(28, 28, 28);
	static final Color LOCK = new Color(230, 185, 60);

	// Translucent, so hover and press work on any surface.
	static final Color HOVER_FILL = new Color(255, 255, 255, 20);
	static final Color PRESS_FILL = new Color(255, 255, 255, 36);

	// Every gap, padding and margin comes from this 4px scale, and padding inside a box is never
	// larger than the space around it.
	static final int SPACE_XS = 4;
	static final int SPACE_S = 8;
	static final int SPACE_M = 12;
	static final int SPACE_L = 16;
	static final int SPACE_XL = 24;

	static final int SIDE = SPACE_S;
	static final int GAP = SPACE_S;
	static final int CONTENT_COLUMN_X = SPACE_L;
	static final int CARD_PAD = CONTENT_COLUMN_X - SIDE;

	static final int CONTROL_SIZE = 24;
	static final int CARD_ARC = 10;
	// Takes the list's right-hand margin while it shows.
	static final int SCROLLBAR_WIDTH = SIDE;

	static final int SPRITE_W = 36;
	static final int SPRITE_H = 32;

	static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	/** Off the font's pixel grid: paint it with {@link #smoothText} or its strokes come out uneven. */
	static Font hero()
	{
		return HERO;
	}

	private static final Font HERO = FontManager.getRunescapeBoldFont().deriveFont(24f);

	static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	/** Antialiased copy of {@code g}; dispose it when done. */
	static Graphics2D smooth(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g2;
	}

	/** For fonts drawn off their pixel grid, where whole-pixel advances space the digits unevenly. */
	static void smoothText(Graphics2D g2)
	{
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
	}

	static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	private Theme()
	{
	}
}

package com.bankstonks.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;

/** Painted by hand, so the controls match each other and ignore the look and feel. */
final class Widgets
{
	static final int CHIP_H = 14;
	private static final int CHIP_PAD = 5;
	private static final int CHIP_TINT_ALPHA = 38;
	private static final int ICON_BUTTON_ARC = 8;
	private static final String CAPITALS_AND_DIGITS = "0123456789H";

	/** Not FlowLayout: it pads both ends too, which knocks the edges off the alignment column. */
	static JPanel hbox(int gap, java.awt.Component... items)
	{
		JPanel row = new JPanel();
		row.setOpaque(false);
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		for (int i = 0; i < items.length; i++)
		{
			if (i > 0)
			{
				row.add(Box.createHorizontalStrut(gap));
			}
			if (items[i] instanceof JComponent)
			{
				((JComponent) items[i]).setAlignmentY(java.awt.Component.CENTER_ALIGNMENT);
			}
			row.add(items[i]);
		}
		return row;
	}

	static JButton iconButton(Icon icon, String tooltip, Runnable action)
	{
		JButton b = new JButton(icon)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = Theme.smooth(g);
				if (getModel().isPressed())
				{
					g2.setColor(Theme.PRESS_FILL);
					g2.fill(new RoundRectangle2D.Double(0, 0, getWidth(), getHeight(), ICON_BUTTON_ARC, ICON_BUTTON_ARC));
				}
				else if (getModel().isRollover() || isSelected())
				{
					g2.setColor(Theme.HOVER_FILL);
					g2.fill(new RoundRectangle2D.Double(0, 0, getWidth(), getHeight(), ICON_BUTTON_ARC, ICON_BUTTON_ARC));
				}
				Icon i = getIcon();
				i.paintIcon(this, g2, (getWidth() - i.getIconWidth()) / 2, (getHeight() - i.getIconHeight()) / 2);
				g2.dispose();
			}
		};
		plain(b);
		b.setToolTipText(tooltip);
		fixSize(b, new Dimension(Theme.CONTROL_SIZE, Theme.CONTROL_SIZE));
		b.addActionListener(e -> action.run());
		return b;
	}

	static JButton primaryButton(String text, Runnable action)
	{
		JButton b = new JButton(text)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = Theme.smooth(g);
				g2.setColor(!isEnabled() ? Theme.OUTLINE
					: getModel().isPressed() ? Theme.ACCENT
					: getModel().isRollover() ? Theme.ACCENT_HOVER : Theme.ACCENT);
				g2.fill(new RoundRectangle2D.Double(0, 0, getWidth(), getHeight(), getHeight(), getHeight()));
				g2.setFont(getFont());
				g2.setColor(isEnabled() ? Theme.TEXT_ON_ACCENT : Theme.TEXT_FAINT);
				FontMetrics fm = g2.getFontMetrics();
				g2.drawString(getText(), (getWidth() - fm.stringWidth(getText())) / 2, baseline(fm, 0, getHeight()));
				g2.dispose();
			}
		};
		plain(b);
		b.setFont(Theme.small());
		b.setPreferredSize(new Dimension(b.getFontMetrics(b.getFont()).stringWidth(text) + 2 * Theme.SPACE_M, Theme.CONTROL_SIZE));
		b.addActionListener(e -> action.run());
		return b;
	}

	/** Keeps FlatLaf's own border, so {@code JComponent.outline = "error"} still works. */
	static JTextField textField(String placeholder, String tooltip, Color background)
	{
		JTextField f = new JTextField();
		f.putClientProperty("JTextField.placeholderText", placeholder);
		f.putClientProperty("FlatLaf.style", "arc: 8; focusWidth: 0; innerFocusWidth: 0; margin: 0,6,0,6;"
			+ " placeholderForeground: " + hex(Theme.TEXT_FAINT));
		f.setBackground(background);
		f.setForeground(Theme.TEXT);
		f.setCaretColor(Theme.TEXT);
		f.setFont(Theme.small());
		f.setToolTipText(tooltip);
		f.setPreferredSize(new Dimension(0, Theme.CONTROL_SIZE));
		return f;
	}

	private static String hex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	static JLabel sectionLabel(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(Theme.small());
		l.setForeground(Theme.TEXT_FAINT);
		return l;
	}

	/**
	 * Masks its corners after the children paint, so a hover fill in the first or last row follows
	 * the rounded edge.
	 */
	static class Card extends JPanel
	{
		Card(LayoutManager layout)
		{
			super(layout);
			setBackground(Theme.SURFACE);
		}

		/** A child's repaint must go through this paint, or it draws over the masked corners. */
		@Override
		public boolean isPaintingOrigin()
		{
			return true;
		}

		@Override
		public void paint(Graphics g)
		{
			super.paint(g);
			Graphics2D g2 = Theme.smooth(g);
			maskCorners(g2);
			paintOutline(g2);
			g2.dispose();
		}

		private void maskCorners(Graphics2D g2)
		{
			int w = getWidth();
			int h = getHeight();
			Shape round = new RoundRectangle2D.Double(0, 0, w, h, Theme.CARD_ARC, Theme.CARD_ARC);
			Area corners = new Area(new Rectangle2D.Double(0, 0, w, h));
			corners.subtract(new Area(round));
			g2.setColor(nearestOpaqueBackground());
			g2.fill(corners);
		}

		private void paintOutline(Graphics2D g2)
		{
			g2.setColor(Theme.OUTLINE);
			g2.draw(new RoundRectangle2D.Double(0.5, 0.5, getWidth() - 1, getHeight() - 1, Theme.CARD_ARC, Theme.CARD_ARC));
		}

		private Color nearestOpaqueBackground()
		{
			for (java.awt.Container p = getParent(); p != null; p = p.getParent())
			{
				if (p.isOpaque())
				{
					return p.getBackground();
				}
			}
			return Theme.CANVAS;
		}
	}

	/** Right-aligned at {@code right}; returns the chip's left edge. */
	static int paintChip(Graphics2D g2, String text, int right, int centerY, Color color)
	{
		FontMetrics fm = g2.getFontMetrics();
		int w = chipWidth(fm, text);
		int x = right - w;
		int y = centerY - CHIP_H / 2;
		g2.setColor(Theme.withAlpha(color, CHIP_TINT_ALPHA));
		g2.fill(new RoundRectangle2D.Double(x, y, w, CHIP_H, CHIP_H, CHIP_H));
		g2.setColor(color);
		g2.drawString(text, x + CHIP_PAD, baseline(fm, y, CHIP_H));
		return x;
	}

	static int chipWidth(FontMetrics fm, String text)
	{
		return fm.stringWidth(text) + 2 * CHIP_PAD;
	}

	/**
	 * Centres the capitals and digits in the box. Measures the real glyph bounds: the RuneScape
	 * fonts report an ascent that doesn't match their glyphs.
	 */
	static int baseline(FontMetrics fm, int top, int height)
	{
		Rectangle2D cap = capBounds(fm);
		return top + (int) Math.round((height - cap.getHeight()) / 2 - cap.getY());
	}

	static double capCenter(FontMetrics fm, int baseline)
	{
		Rectangle2D cap = capBounds(fm);
		return baseline + cap.getY() + cap.getHeight() / 2;
	}

	private static final java.util.Map<java.awt.Font, Rectangle2D> CAP_BOUNDS = new java.util.HashMap<>();

	/** Relative to the baseline, so y is negative. */
	private static Rectangle2D capBounds(FontMetrics fm)
	{
		return CAP_BOUNDS.computeIfAbsent(fm.getFont(),
			f -> f.createGlyphVector(fm.getFontRenderContext(), CAPITALS_AND_DIGITS).getVisualBounds());
	}

	static String ellipsize(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String dots = "…";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + dots) > width)
		{
			end--;
		}
		return text.substring(0, end).trim() + dots;
	}

	static void fixSize(JComponent c, Dimension size)
	{
		c.setPreferredSize(size);
		c.setMinimumSize(size);
		c.setMaximumSize(size);
	}

	static void plain(JButton b)
	{
		b.setContentAreaFilled(false);
		b.setBorderPainted(false);
		b.setFocusPainted(false);
		b.setOpaque(false);
		b.setRolloverEnabled(true);
		b.setBorder(new EmptyBorder(0, 0, 0, 0));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	private Widgets()
	{
	}
}

